UIGarageTankIconImage=function(game,playerId,hitFunction,context){this.playerId=playerId;this.iconWidth=UIConstants.TANK_ICON_WIDTH_LARGE;this.iconHeight=UIConstants.TANK_ICON_HEIGHT_LARGE;this.size=UIConstants.TANK_ICON_SIZES.LARGE;Phaser.Image.call(this,game,0,0,game.add.bitmapData(this.iconWidth,this.iconHeight));this.anchor.setTo(0.5,0.5);this.tankIconPlaceholder=this.addChild(new Phaser.Image(game,0,0,'tankiconplaceholder-'+this.size));this.tankIconPlaceholder.anchor.setTo(0.5,0.5);this.showingDetails=false;this.turretColour=null;this.treadColour=null;this.baseColour=null;this.accessories={};this.spawnTween=null;this.removeTween=null;this.inputEnabled=true;this.events.onInputUp.add(hitFunction,context);this.kill();this.scale.set(0.0,0.0);var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){self.turretColour=result.getTurretColour();self.treadColour=result.getTreadColour();self.baseColour=result.getBaseColour();self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.TURRET]=result.getTurretAccessory();self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BARREL]=result.getBarrelAccessory();self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.FRONT]=result.getFrontAccessory();self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BACK]=result.getBackAccessory();}else{self.turretColour=UIConstants.TANK_UNAVAILABLE_COLOUR;self.treadColour=UIConstants.TANK_UNAVAILABLE_COLOUR;self.baseColour=UIConstants.TANK_UNAVAILABLE_COLOUR;self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.TURRET]=null;self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BARREL]=null;self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.FRONT]=null;self.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BACK]=null;}self._updateIcon();self.showingDetails=true;},function(result){},function(result){},this.playerId,Caches.getPlayerDetailsCache());this.log=Log.create('UIGarageTankIconImage');}
UIGarageTankIconImage.prototype=Object.create(Phaser.Image.prototype);UIGarageTankIconImage.prototype.constructor=UIGarageTankIconImage;UIGarageTankIconImage.prototype.update=function(){}
UIGarageTankIconImage.prototype.paintTurret=function(self,newColour){if(newColour.rawValue!=self.turretColour.rawValue){self.turretColour=newColour;self._storeColour("turret",newColour);self._updateIcon();}}
UIGarageTankIconImage.prototype.paintTread=function(self,newColour){if(newColour.rawValue!=self.treadColour.rawValue){self.treadColour=newColour;self._storeColour("tread",newColour);self._updateIcon();}}
UIGarageTankIconImage.prototype.paintBase=function(self,newColour){if(newColour.rawValue!=self.baseColour.rawValue){self.baseColour=newColour;self._storeColour("base",newColour);self._updateIcon();}}
UIGarageTankIconImage.prototype.applyAccessory=function(newAccessoryType,newAccessoryNumber){if(newAccessoryNumber!=this.accessories[newAccessoryType]){this.accessories[newAccessoryType]=newAccessoryNumber;this._storeAccessory(newAccessoryType,newAccessoryNumber);}else{delete this.accessories[newAccessoryType];this._storeAccessory(newAccessoryType,0);}this._updateIcon();}
UIGarageTankIconImage.prototype.getAccessory=function(accessoryType){return this.accessories[accessoryType];}
UIGarageTankIconImage.prototype._storeColour=function(place,colour){var self=this;Backend.getInstance().setColour(function(result){Users.updateUser(self.playerId,true,false);},function(result){},function(result){},this.playerId,place,colour.rawValue,Caches.getPlayerDetailsCache());}
UIGarageTankIconImage.prototype._storeAccessory=function(type,number){var self=this;Backend.getInstance().setAccessory(function(result){Users.updateUser(self.playerId,true,false);},function(result){},function(result){},this.playerId,type,number,Caches.getPlayerDetailsCache());}
UIGarageTankIconImage.prototype._updateIcon=function(){UITankIcon.loadTankIcon(this.key.canvas,this.size,this.turretColour,this.treadColour,this.baseColour,this.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.TURRET],this.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BARREL],this.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.FRONT],this.accessories[UIConstants.TANK_ICON_ACCESSORY_PARTS.BACK],null,null,null,function(self){self.tankIconPlaceholder.kill();self.key.clear();},this);}
UIGarageTankIconImage.prototype.spawn=function(x,y){this.reset(x,y);if(this.removeTween){this.removeTween.stop();}this.spawnTween=this.game.add.tween(this.scale).to({x:1.0,y:1.0},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}
UIGarageTankIconImage.prototype.getPlayerId=function(){return this.playerId;}
UIGarageTankIconImage.prototype.disable=function(){this.inputEnabled=false;}
UIGarageTankIconImage.prototype.enable=function(){this.inputEnabled=true;this.input.useHandCursor=true;}
UIGarageTankIconImage.prototype.remove=function(){this.showingDetails=false;if(this.spawnTween){this.spawnTween.stop();}this.removeTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.removeTween.onComplete.add(function(){this.kill();},this);}
UIGarageTankIconImage.prototype.retire=function(){this.kill();}